import{_ as i}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as l,D as g,o as r,c as p,I as h,w as c,k as o,a as d,R as u,b as A,e as f}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const y=JSON.parse('{"title":"Agent 框架与运行时","description":"","frontmatter":{"title":"Agent 框架与运行时","author":"阿源","date":"2026/10/07 00:00","categories":["Agent 开发"],"tags":["Agent","Runtime","Framework"],"status":"预览版导航"},"headers":[],"relativePath":"courses/agent/01-项目与知识库导航/02-Agent框架与运行时.md","filePath":"courses/agent/01-项目与知识库导航/02-Agent框架与运行时.md","lastUpdated":1791355601000}'),_={name:"courses/agent/01-项目与知识库导航/02-Agent框架与运行时.md"},m=o("h1",{id:"agent-框架与运行时",tabindex:"-1"},[d("Agent 框架与运行时 "),o("a",{class:"header-anchor",href:"#agent-框架与运行时","aria-label":'Permalink to "Agent 框架与运行时"'},"​")],-1),k=u('<p>这一页解决“先看哪个运行时”的问题。阅读顺序是：先用 smolagents 建立最小 loop，再看 OpenAI Agents SDK 如何托管常见运行时能力，随后用 Responses API 理解更低层的自主管理边界，最后用 LangGraph 观察显式状态图如何承载长流程。不要先背框架 API；先回到 <a href="/courses/agent/02-Agent基础/01-Agent是什么">02 Agent 基础</a> 的 Model、Tools、State 和 StopReason。</p><h2 id="smolagents" tabindex="-1">smolagents <a class="header-anchor" href="#smolagents" aria-label="Permalink to &quot;smolagents&quot;">​</a></h2><p>官方入口：<a href="https://github.com/huggingface/smolagents" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://huggingface.co/docs/smolagents/" target="_blank" rel="noreferrer">官方文档</a></p><ul><li><strong>解决的问题</strong>：用很少的抽象搭建可读的 Agent Loop、工具和代码执行 Agent。</li><li><strong>推荐学习内容</strong>：先运行一个本地、只读工具，再阅读 Agent 与 CodeAgent 的循环、停止和执行器边界。</li><li><strong>前置知识</strong>：Python 函数与异常处理；已理解 Agent Loop、Tool 的直觉。</li><li><strong>学习阶段</strong>：入门。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：README 的核心抽象、<code>docs/source/en/tutorials/overview.mdx</code>、<code>src/smolagents/agents.py</code>。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Agent Loop、Tool 与 CodeAgent 对应 dsh 的 Agent Driver、工具插件和执行沙箱边界；两者不是 API 等价。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="openai-agents-sdk" tabindex="-1">OpenAI Agents SDK <a class="header-anchor" href="#openai-agents-sdk" aria-label="Permalink to &quot;OpenAI Agents SDK&quot;">​</a></h2><p>官方入口：<a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://openai.github.io/openai-agents-python/" target="_blank" rel="noreferrer">官方文档</a></p><ul><li><strong>解决的问题</strong>：把 Agent、工具、handoff、guardrail、session 和 tracing 组合成可观测运行时。</li><li><strong>推荐学习内容</strong>：按 Quickstart → Agents → Running agents → Handoffs → Guardrails → Tracing 阅读，比较托管 Runner 与自建循环。</li><li><strong>前置知识</strong>：Python 类型标注和数据校验的基本概念；第 02–04 章。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：Quickstart、Agents、Running agents、Tracing。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Agent/Runner、handoff 和 tracing 对应 dsh 的 driver、插件协作和事件流；session 的持久化语义需分别核对。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="openai-responses-api" tabindex="-1">OpenAI Responses API <a class="header-anchor" href="#openai-responses-api" aria-label="Permalink to &quot;OpenAI Responses API&quot;">​</a></h2><p>官方入口：<a href="https://platform.openai.com/docs/guides/agents" target="_blank" rel="noreferrer">Agents 指南</a> · <a href="https://platform.openai.com/docs/api-reference/responses" target="_blank" rel="noreferrer">Responses API</a></p><ul><li><strong>解决的问题</strong>：在需要自主管理模型请求、工具循环和状态时提供较低层的 Agent 原语。</li><li><strong>推荐学习内容</strong>：查 function calling、streaming 和 conversation state，理解何时把 loop 责任留在应用层。</li><li><strong>前置知识</strong>：第 02–04 章；HTTP JSON API 基础。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：Agents guide、Tools、Conversation state、Streaming events。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Responses turn 与 tool result 可映射到 dsh 的 driver turn 和事件记录，但 Responses API 不等同于插件架构。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="langgraph" tabindex="-1">LangGraph <a class="header-anchor" href="#langgraph" aria-label="Permalink to &quot;LangGraph&quot;">​</a></h2><p>官方入口：<a href="https://github.com/langchain-ai/langgraph" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://docs.langchain.com/oss/python/langgraph/" target="_blank" rel="noreferrer">Python 文档</a></p><ul><li><strong>解决的问题</strong>：用显式 State、Node、Edge、checkpoint 和 interrupt 编排长流程、恢复与人工介入。</li><li><strong>推荐学习内容</strong>：先做单 Agent StateGraph，再阅读 checkpointer、interrupt、durable execution 和多 Agent 路由。</li><li><strong>前置知识</strong>：第 02–05、09 章；Python 状态机思维。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：主线精读。</li><li><strong>推荐目录/文章</strong>：Graph API、Persistence / Checkpointers、Interrupts、Durable execution。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：State/checkpoint/interrupt 对应 dsh 的 Session、Hook 和可恢复事件；图节点并不等于 dsh plugin。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="选型检查表" tabindex="-1">选型检查表 <a class="header-anchor" href="#选型检查表" aria-label="Permalink to &quot;选型检查表&quot;">​</a></h2><ol><li>如果只有一个短循环和少量确定性工具，先保留 Python 函数和显式状态，不急着引入框架。</li><li>如果需要标准化 handoff、guardrail、session 或 tracing，阅读 OpenAI Agents SDK 的运行时职责。</li><li>如果流程有长时间等待、多个分支、人工介入或恢复要求，阅读 LangGraph 的 checkpoint 和 interrupt 语义。</li><li>如果要研究插件化 Coding Agent，跳到 <a href="/courses/agent/01-项目与知识库导航/03-Coding-Agent与Harness">Coding Agent 与 Harness</a> 和最后的 DeepSeek Harness 导读。</li></ol>',15);function b(e,P,S,I,D,R){const a=i,s=g("ClientOnly");return r(),p("div",null,[m,h(s,null,{default:c(()=>{var t,n;return[(((t=e.$frontmatter)==null?void 0:t.aside)??!0)&&(((n=e.$frontmatter)==null?void 0:n.showArticleMetadata)??!0)?(r(),A(a,{key:0,article:e.$frontmatter},null,8,["article"])):f("",!0)]}),_:1}),k])}const v=l(_,[["render",b]]);export{y as __pageData,v as default};
